    ok('[F] prémisse F044 : après 50 × 8, le coach propose 55 — la charge du test prévu — sur la série 2 (reps à taper)',
      g4[1].charAt(0) === '*' && /^\*55×/.test(g4[1]), nbF(g4));
    await saisirSerie(1, 50, 6);
    await attendre(900);
